// src/helpers/sequence-annotation.ts
var getSequenceAnnotationMetadata = ({
  sequence,
  location
}) => {
  const metadata = {
    layer: (sequence.displayName || sequence.controls?.componentName || "Layer").slice(0, 128),
    ...Number.isFinite(sequence.from) ? { from: sequence.from } : {},
    ...Number.isFinite(sequence.duration) ? { duration: sequence.duration } : {}
  };
  const relativeLocation = getRelativeFileLocation({
    location,
    root: window.remotion_cwd
  });
  if (relativeLocation && relativeLocation.filename.length <= 256) {
    const withSource = {
      ...metadata,
      source: relativeLocation.filename,
      line: relativeLocation.line
    };
    if (new TextEncoder().encode(JSON.stringify(withSource)).length <= 2048) {
      return withSource;
    }
  }
  return metadata;
};

